#include <algorithm>

int clampPrice(int p) {
    // Compiler typically emits cmov here - no branch, no misprediction risk:
    return std::max(0, std::min(p, 100));
}

// Explicit branchless select using an all-ones/all-zeros mask:
// mask = -(condition) is 0xFFFFFFFF when true, 0x00000000 when false.
int capped(int p, int limit) {
    int over = -(p > limit);              // mask: all-ones iff p > limit
    return (p & ~over) | (limit & over);  // pick p or limit per bit
}

#include <numeric>
#include <vector>

// Compile with: g++ -O3 -march=native -ftree-vectorize
// (verify with -fopt-info-vec: 'loop vectorized using 16 byte vectors')
double dot(const std::vector<double>& a, const std::vector<double>& b) {
    return std::inner_product(a.begin(), a.end(), b.begin(), 0.0);
}
// At -O3 -march=native the compiler maps this loop to vfmadd/vaddpd
// instructions: 4 doubles per AVX2 instruction, 8 with AVX-512.
// Contiguous input (SoA) is what makes this possible.

